const input = $input.first().json;
const event = input.body;
const failure = (type) => [{json: {valid: false, event: {trace_id: typeof event?.trace_id === 'string' && event.trace_id.trim() ? event.trace_id.trim().slice(0,128) : 'unknown', language: 'pt-BR'}, failureType: type}}];
const object = v => v !== null && typeof v === 'object' && !Array.isArray(v);
const keys = (v, allowed) => Object.keys(v).every(k => allowed.includes(k));
const text = (v, max=500) => typeof v === 'string' && v.length <= max;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!object(event) || !keys(event,['event_type','event_id','occurred_at','trace_id','channel','recipient','language','itinerary']) || event.event_type !== 'turismo.roteiro.despachar' || !uuid.test(event.event_id) || !text(event.occurred_at,64) || !Number.isFinite(Date.parse(event.occurred_at)) || !text(event.trace_id,128) || !event.trace_id.trim() || !text(event.language,16)) return failure('InvalidDispatchEvent');
const r = event.recipient;
if (!object(r) || !keys(r,['name','email','phone']) || !text(r.name,80) || !r.name.trim()) return failure('InvalidRecipient');
// SMTP accepts recipient lists: reject separators and control characters explicitly.
if (event.channel === 'email') {
  if (!text(r.email,254) || !/^[^\s@,;<>"\x00-\x1f\x7f]+@[^\s@,;<>"\x00-\x1f\x7f]+\.[^\s@,;<>"\x00-\x1f\x7f]+$/.test(r.email)) return failure('InvalidRecipient');
} else if (event.channel === 'whatsapp') {
  if (!text(r.phone,16) || !/^\+[1-9][0-9]{7,14}$/.test(r.phone)) return failure('InvalidRecipient');
} else return failure('InvalidChannel');
const t = event.itinerary;
if (!object(t) || !keys(t,['trip_id','title','origin','destination','distance_km','duration_min','summary','days','map_url']) || !text(t.trip_id,128) || !text(t.title) || !text(t.origin) || !text(t.destination) || (t.summary != null && !text(t.summary)) || !Array.isArray(t.days) || t.days.length < 1 || t.days.length > 30) return failure('InvalidItinerary');
for (const day of t.days) {
  if (!object(day) || !Number.isInteger(day.day) || day.day < 1 || !Array.isArray(day.activities) || day.activities.length > 20) return failure('InvalidItinerary');
  for (const a of day.activities) if (!object(a) || !text(a.title) || (a.time != null && !text(a.time,80)) || (a.description != null && !text(a.description))) return failure('InvalidItinerary');
}
for (const key of ['distance_km','duration_min']) if (t[key] != null && (typeof t[key] !== 'number' || !Number.isFinite(t[key]) || t[key] < 0)) return failure('InvalidItinerary');
if (t.map_url != null && (!text(t.map_url,2048) || !/^https?:\/\/[^\s<>"']+$/i.test(t.map_url))) return failure('InvalidMapUrl');
const config = $('Config').first().json;
if (!text(config.fromEmail,254) || !/^[^\s@,;<>"\x00-\x1f\x7f]+@[^\s@,;<>"\x00-\x1f\x7f]+\.[^\s@,;<>"\x00-\x1f\x7f]+$/.test(config.fromEmail) || !['local','staging','production'].includes(config.environment)) return failure('InvalidConfiguration');
const state = $getWorkflowStaticData('global');
if ((state.sentEventIds || []).includes(event.event_id)) return [];
return [{json: {valid: true, event}}];

const event = $input.first().json.event;
const t = event.itinerary;
const translations = {
  'pt-BR': {subject:'Seu roteiro', day:'Dia', map:'Ver no mapa', route:'Trajeto'},
  en: {subject:'Your itinerary', day:'Day', map:'View on map', route:'Route'}
};
const language = Object.hasOwn(translations,event.language) ? event.language : 'pt-BR';
const l = translations[language];
const escape = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const days = t.days.map(day => `<tr><td style="padding:16px 24px"><h2 style="font-size:20px;margin:0 0 12px">${l.day} ${day.day}</h2>${day.activities.map(a => `<p style="margin:0 0 12px;line-height:1.6"><strong>${[a.time, a.title].filter(value => value != null && value !== '').map(escape).join(' ')}</strong>${a.description != null && a.description !== '' ? '<br>' + escape(a.description) : ''}</p>`).join('')}</td></tr>`).join('');
const map = t.map_url ? `<tr><td style="padding:24px"><a href="${escape(t.map_url)}" style="background:#166534;color:#ffffff;padding:12px 20px;text-decoration:none;display:inline-block">${l.map}</a></td></tr>` : '';
const html = `<!doctype html><html lang="${language}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;background:#f3f4f6;font-family:Arial,sans-serif;color:#17212b"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 12px"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff"><tr><td style="padding:24px;background:#166534;color:#ffffff"><h1 style="margin:0;font-size:26px">${escape(t.title)}</h1></td></tr><tr><td style="padding:24px"><p>${escape(event.recipient.name)}</p><p><strong>${l.route}:</strong> ${escape(t.origin)} → ${escape(t.destination)}</p><p style="line-height:1.6">${escape(t.summary)}</p></td></tr>${days}${map}</table></td></tr></table></body></html>`;
return [{json: {event, to:event.recipient.email, subject:`${l.subject}: ${t.title}`.replace(/[\r\n\x00-\x1f\x7f]/g,' '), html}}];

const event = $('Montar email').first().json.event;
const state = $getWorkflowStaticData('global');
state.sentEventIds = [...(state.sentEventIds || []).filter(id => id !== event.event_id), event.event_id].slice(-50);
return [{json:{delivered:true,event_id:event.event_id,trace_id:event.trace_id}}];

const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {const r=Math.floor(Math.random()*16);return (c==='x'?r:(r&3|8)).toString(16);});
const e = $input.first().json.event;
const messages = {InvalidConfiguration:'Configuração do remetente ou ambiente pendente.',InvalidDispatchEvent:'Evento de despacho inválido.',InvalidRecipient:'Destinatário inválido.',InvalidChannel:'Canal inválido.',InvalidItinerary:'Roteiro inválido.',InvalidMapUrl:'Link do mapa inválido.',EmailDeliveryFailed:'Não foi possível entregar o e-mail.',WhatsAppNotEnabled:'Canal WhatsApp ainda não habilitado (P2).'};
// Never forward provider errors: they may contain recipient addresses or credentials.
const type = Object.hasOwn(messages,$input.first().json.failureType) ? $input.first().json.failureType : 'EmailDeliveryFailed';
return [{json:{event_type:'turismo.falha',event_id:uuid(),occurred_at:new Date().toISOString(),trace_id:e.trace_id,environment: ['local','staging','production'].includes($('Config').first().json.environment) ? $('Config').first().json.environment : 'production',request:{method:'POST',route:'turismo-despachar-roteiro',status_code:502,language:e.language},error:{type,message:messages[type],stack_trace:''}}}];
